USE sakila;

-- List the number of films per category.

SELECT * FROM film_category;

SELECT category_id, COUNT(film_id) AS number_of_films
FROM film_category
GROUP BY category_id
ORDER BY category_id ASC;

-- Retrieve the store ID, city, and country for each store.

SELECT store.store_id, city.city, country.country
FROM store
JOIN address ON store.address_id = address.address_id
JOIN city ON address.city_id = city.city_id
JOIN country ON city.country_id = country.country_id;

-- Calculate the total revenue generated by each store in dollars.

SELECT 
    store.store_id, 
    SUM(payment.amount) AS total_revenue
FROM 
    payment
JOIN 
    rental ON payment.rental_id = rental.rental_id
JOIN 
    inventory ON rental.inventory_id = inventory.inventory_id
JOIN 
    store ON inventory.store_id = store.store_id
GROUP BY 
    store.store_id
ORDER BY 
    total_revenue DESC;
    
    SELECT * FROM store;
	SELECT * FROM payment;
    SELECT * FROM rental;
    SELECT * FROM inventory;
    
    -- Determine the average running time of films for each category.
    
    SELECT * FROM category;
    SELECT * FROM film_category;
    SELECT * FROM film;
    
    SELECT 
    category.name, AVG(film.length) AS average_running_time
FROM
    film
        JOIN
    film_category ON film.film_id = film_category.film_id
        JOIN
    category ON film_category.category_id = category.category_id
GROUP BY category.name
ORDER BY average_running_time DESC;
    
    -- Identify the film categories with the longest average running time.
    
    SELECT 
    category.name, AVG(film.length) AS average_running_time
FROM
    film
        JOIN
    film_category ON film.film_id = film_category.film_id
        JOIN
    category ON film_category.category_id = category.category_id
GROUP BY category.name
ORDER BY average_running_time DESC
LIMIT 5;
    
    -- Display the top 10 most frequently rented movies in descending order.Display the top 10 most frequently rented movies in descending order.v
    
  SELECT 
    film.title, COUNT(rental.rental_id) AS rental_count
FROM
    rental
        JOIN
    inventory ON rental.inventory_id = inventory.inventory_id
        JOIN
    film ON inventory.film_id = film.film_id
GROUP BY film.title
ORDER BY rental_count DESC
LIMIT 10;

-- Determine if "Academy Dinosaur" can be rented from Store 1.

SELECT 
    CASE
        WHEN COUNT(inventory.inventory_id) > 0 THEN 'Available'
        ELSE 'Not Available'
    END AS availability
FROM
    film
        JOIN
    inventory ON film.film_id = inventory.film_id
WHERE
    film.title = 'Academy Dinosaur'
        AND inventory.store_id = 1;

-- Provide a list of all distinct film titles, along with their availability status in the inventory. Include a column indicating whether each title is 'Available' or 'NOT available.' Note that there are 42 titles that are not in the inventory, and this information can be obtained using a CASE statement combined with IFNULL."

SELECT 
    film.title,
    CASE
        WHEN COUNT(inventory.inventory_id) > 0 THEN 'Available'
        ELSE 'NOT Available'
    END AS availability_status
FROM
    film
        LEFT JOIN
    inventory ON film.film_id = inventory.film_id
GROUP BY film.title
ORDER BY film.title;